public int MinMeetingRoomsBrute(int[][] intervals)
{
    int best = 0;

    foreach (var a in intervals)
    {
        int overlapping = 0;
        foreach (var b in intervals)
        {
            // b overlaps a if b starts before a ends and ends after a starts
            if (b[0] < a[1] && b[1] > a[0]) overlapping++;
        }
        best = Math.Max(best, overlapping);
    }

    return best;
}

public int MinMeetingRooms(int[][] intervals)
{
    if (intervals.Length == 0) return 0;

    Array.Sort(intervals, (a, b) => a[0].CompareTo(b[0]));

    // End times of meetings currently in progress
    var endTimes = new PriorityQueue<int, int>();
    int rooms = 0;

    foreach (var meeting in intervals)
    {
        int start = meeting[0];
        int end = meeting[1];

        // Free any room whose meeting has ended by now
        if (endTimes.Count > 0 && endTimes.Peek() <= start)
        {
            endTimes.Dequeue();
        }

        endTimes.Enqueue(end, end);
        rooms = Math.Max(rooms, endTimes.Count);
    }

    return rooms;
}

public int MinMeetingRoomsSweep(int[][] intervals)
{
    int n = intervals.Length;
    if (n == 0) return 0;

    var starts = new int[n];
    var ends = new int[n];

    for (int i = 0; i < n; i++)
    {
        starts[i] = intervals[i][0];
        ends[i] = intervals[i][1];
    }

    Array.Sort(starts);
    Array.Sort(ends);

    int rooms = 0;
    int endPointer = 0;

    for (int i = 0; i < n; i++)
    {
        if (starts[i] < ends[endPointer]) rooms++;  // a new room is needed
        else endPointer++;                          // reuse a freed room
    }

    return rooms;
}

public int MinMeetingRooms(int[][] intervals)
{
    if (intervals.Length == 0) return 0;
    Array.Sort(intervals, (a, b) => a[0].CompareTo(b[0]));

    var endTimes = new PriorityQueue<int, int>();
    int rooms = 0;

    foreach (var meeting in intervals)
    {
        if (endTimes.Count > 0 && endTimes.Peek() <= meeting[0]) endTimes.Dequeue();
        endTimes.Enqueue(meeting[1], meeting[1]);
        rooms = Math.Max(rooms, endTimes.Count);
    }

    return rooms;
}
